// 1. Standard 'inline' usage and ODR compliance

inline int fast_add(int a, int b) {
    // Suggestion to the compiler:
    // Replace call site with function body.
    return a + b;
}

void use_add() {
    int sum = fast_add(10, 20);
    // Compiler avoids function call overhead if inlined.
}


// 2. Implicit Inlining (Defined in Class Body)

class Widget {
    int state;
public:
    // Implicit inline candidate (defined within header scope)
    int getState() const { return state; }

    // Must use explicit 'inline' keyword if defined outside class
    // in the header to ensure ODR compliance across TUs.
    void setState(int s) { state = s; }
};


// 3. Forcing Inlining (Compiler Attributes - GCC/Clang)

// Overrides heuristic; forces inline regardless of size
__attribute__((always_inline))
void tiny_helper() { /* ... */ }

// Prevents inlining (e.g., for debugging/profiling stability)
__attribute__((noinline))
void debug_routine() { /* ... */ }


// 4. C++20 `[[likely]]` / PGO impact (related concept)

int process(int i) {
    if (i > 10) [[likely]] {
        return i * 2; // High probability path
        // Compiler may optimize/inline this branch aggressively
    }
    return i;
}
